18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
36	
37	export interface ScenarioResult {
38	  results: StepResult[];
39	}
40	
41	const PROCESSING_FEE = 5;
42	
43	const FIRST_INSURANCE_PERCENT = 10;
44	
45	const BASE_PREMIUMS: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	};
49	
50	// Percentages are applied as exact integer fractions; floating-point
51	// multiplication drifts (100 * 1.1 === 110.00000000000001) and the spec
52	// rounds only at the very end.
53	const quote = ({ items }: QuoteStep): StepResult => {
54	  const base = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
55	  const withSurcharge = (base * (100 + FIRST_INSURANCE_PERCENT)) / 100;
56	
57	  return { premium: Math.ceil(withSurcharge + PROCESSING_FEE) };
58	};
59	
60	export const runScenario = (scenario: Scenario): ScenarioResult => ({
61	  // Only quote steps are exercised so far; claim dispatch arrives with its first test.
62	  results: scenario.steps.map((step) => quote(step as QuoteStep)),
63	});
