// Percentages MUST go through this helper. Applying them as exact integer
// fractions keeps the arithmetic drift-free; the tempting `amount * 1.1`
// yields 110.00000000000001 for 100, and since the spec rounds premiums UP
// at the very end that drift becomes a whole extra G.
const addPercent = (amount: number, percent: number): number =>
  (amount * (100 + percent)) / 100;

const quote = ({ items }: QuoteStep): StepResult => {
  const policyBase = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  const withFirstInsurance = addPercent(policyBase, FIRST_INSURANCE_PERCENT);

  return { premium: Math.ceil(withFirstInsurance + PROCESSING_FEE) };
};
